using Xunit;

namespace Dexpace.Sdk.Conformance.Tests.Gates;

/// <summary>
/// NFR-13 (phase 10, P10-12, V11): every C# source file of the repository starts with the two-line MIT header, an <c>&lt;auto-generated&gt;</c>
/// block allowed before it. <c>IDE0073</c> already enforces it, as a build error, for every file a project compiles; this test closes its one
/// blind spot, the file-based apps under <c>scripts/ci/</c> that no project compiles. Project and build files are not "source files" under this reading.
/// </summary>
[Trait("Category", "Unit")]
public sealed class LicenseHeaderTests
{
    private const string First = "// Copyright (c) 2026 dexpace and Omar Aljarrah.";
    private const string Second = "// Licensed under the MIT License. See LICENSE in the repository root for details.";

    private static readonly string[] s_roots = ["src", "tests", "tools", "scripts", ".claude"];

    [Fact]
    public void Every_cs_file_starts_with_the_two_line_header()
    {
        var offenders = Offenders(RepositoryRoot.Path);

        Assert.Empty(offenders);
    }

    [Fact]
    public void Scanned_at_least_900_files_and_the_ci_scripts_among_them()
    {
        // A scan that silently found nothing would pass for the wrong reason (V11: 956 at the time of the design; the repository only grows).
        var files = SourceFiles(RepositoryRoot.Path).ToList();

        Assert.True(files.Count >= 900, $"{files.Count} files scanned");
        Assert.Contains(files, static f => f.EndsWith(Path.Combine("scripts", "ci", "dependency-audit.cs"), StringComparison.Ordinal));
        Assert.Contains(files, static f => f.EndsWith(Path.Combine("scripts", "ci", "packaging-conformance.cs"), StringComparison.Ordinal));
        Assert.Contains(files, static f => f.EndsWith("RequirementCatalog.g.cs", StringComparison.Ordinal));
    }

    [Fact]
    public void The_scan_can_fail()
    {
        var root = Directory.CreateTempSubdirectory("header");
        try
        {
            var scripts = Directory.CreateDirectory(Path.Combine(root.FullName, "scripts"));
            File.WriteAllText(Path.Combine(scripts.FullName, "good.cs"), First + "\n" + Second + "\n\nclass A;\n");
            File.WriteAllText(Path.Combine(scripts.FullName, "none.cs"), "class B;\n");
            File.WriteAllText(Path.Combine(scripts.FullName, "second-line.cs"), "// a comment\n" + First + "\n" + Second + "\n");
            File.WriteAllText(Path.Combine(scripts.FullName, "half.cs"), First + "\nclass C;\n");
            File.WriteAllText(Path.Combine(scripts.FullName, "generated-good.cs"), "// <auto-generated>\n// x\n// </auto-generated>\n" + First + "\n" + Second + "\n");
            File.WriteAllText(Path.Combine(scripts.FullName, "generated-bad.cs"), "// <auto-generated>\n// x\n// </auto-generated>\nclass D;\n");
            var obj = Directory.CreateDirectory(Path.Combine(scripts.FullName, "obj"));
            File.WriteAllText(Path.Combine(obj.FullName, "ignored.cs"), "class E;\n");

            Assert.Equal(
                [Path.Combine("scripts", "generated-bad.cs"), Path.Combine("scripts", "half.cs"), Path.Combine("scripts", "none.cs"), Path.Combine("scripts", "second-line.cs")],
                Offenders(root.FullName));
        }
        finally
        {
            root.Delete(recursive: true);
        }
    }

    private static List<string> Offenders(string root) =>
        [.. SourceFiles(root).Where(static file => !HasHeader(File.ReadAllLines(file))).Select(file => Path.GetRelativePath(root, file)).Order(StringComparer.Ordinal)];

    private static IEnumerable<string> SourceFiles(string root) =>
        s_roots
            .Select(sub => Path.Combine(root, sub))
            .Where(Directory.Exists)
            .SelectMany(dir => Directory.EnumerateFiles(dir, "*.cs", SearchOption.AllDirectories))
            .Where(static file => !InBuildOutput(file));

    private static bool InBuildOutput(string file)
    {
        var parts = file.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        return parts.Contains("bin") || parts.Contains("obj");
    }

    private static bool HasHeader(string[] lines)
    {
        var start = 0;
        if (lines.Length > 0 && lines[0].StartsWith("// <auto-generated", StringComparison.Ordinal))
        {
            start = Array.FindIndex(lines, static line => line.StartsWith("// </auto-generated>", StringComparison.Ordinal)) + 1;
            if (start == 0)
            {
                return false;
            }
        }

        return lines.Length >= start + 2 && lines[start] == First && lines[start + 1] == Second;
    }
}
